function finishJobs(){for(const [id,t] of pending()){if(t.due>flow.clock)continue;t.status='done';completeJob(id);}}
function advance(){const jobs=pending();if(!jobs.length)return;clockRemainder=0;flow.clock=jobs[0][1].due;finishJobs();renderChat();save();}
function startJob(id){const j=jobTypes[id];if(!j)return;if(flow.solved){reply('Der Fall ist abgeschlossen. Sie können die Unterlagen weiter lesen oder einen neuen Durchlauf starten.');return;}if(contact!==j.channel){reply('Dafür ist '+contacts[j.channel].name+' zuständig. Wechseln Sie zu „'+channelLabel(j.channel)+'“. Ich habe keinen Auftrag ausgelöst.');return;}const old=flow.tasks[id];if(old){reply(old.status==='pending'?'Der Auftrag läuft bereits bis '+hhmm(old.due)+'. Die Zeit läuft während Ihrer Arbeit. Sie können sie pausieren oder vorspulen.':'Die Rückmeldung liegt bereits vor.',old.status==='done'?[id==='arrest'&&flow.warned?'fugitive':j.doc]:[]);return;}const need=missing(id);if(need.length){reply('Dafür fehlt noch eine Grundlage. '+(id==='lab'?'Es liegen noch keine passenden gesicherten Proben vor. Die Spurensicherung übernimmt Ortiz.':id==='rescue'?'Uns fehlen aktuelle Feststellungen zum Aufenthaltsort. Ein Team muss den Ort zunächst überprüfen.':id==='arrest'?'Ein Verdacht allein genügt hier nicht für die Festnahme. Sichern Sie weitere Tatsachen und klären Sie Jamies Aufenthaltsort.':'Person, Ort oder Material sind für diesen Auftrag noch nicht ausreichend zugeordnet. Prüfen Sie die vorhandenen Unterlagen und Rückmeldungen.')+' Kein Auftrag ausgelöst.');return;}flow.tasks[id]={status:'pending',due:flow.clock+j.minutes};if(id==='harbor'&&onboarding.step!=='done'){onboarding.step='waiting';renderGuide();}reply(j.title+': übernommen. Rückmeldung bis '+hhmm(flow.clock+j.minutes)+'. '+(id==='lab'?'Der Vergleich dauert mehrere Stunden Fallzeit. Setzen Sie die Suche unbedingt parallel fort.':'Sie können weitere Aufträge erteilen oder zur nächsten Rückmeldung vorspulen.'));}
function channelLabel(c){return {ellis:'Ellis',ortiz:'Außendienst',digital:'Recherche',lab:'Labor',medical:'Medizin'}[c];}
function availableJobs(c){return Object.entries(jobTypes).filter(([id,j])=>j.channel===c&&!flow.tasks[id]&&!missing(id).length);}
function hint(){flow.hintLevel++;const stages=[
 [!flow.read.includes('phone'),'Vergleichen Sie die letzte Nachricht mit dem Alltagston der beiden.','Öffnen Sie E-001. Was ist anders an der Abholung und am genannten Freund?','phone'],
 [!known('harbor'),'Der letzte bekannte Aufenthaltsort ist noch nicht überprüft.','Ortiz kann ein Team zum Harbor House schicken.','mother'],
 [!known('mercer'),'Eine Sichtung ist nur eine Seite eines Zeitablaufs.','Lassen Sie Mercer nach seiner Abfahrt und seinem Kontakt zu Jamie fragen.','harbor'],
 [!known('camera'),'Ein unabhängiger Beleg könnte die Zeitangaben prüfen.','Park kann die Apothekenkamera auswerten. Sie wird im Einsatzbericht genannt.','harbor'],
 [!known('locations'),'Wohin konnte der beobachtete Wagen gefahren sein?','Lassen Sie Park die Fahrzeugroute und Mercers Nutzungsorte recherchieren.','camera'],
 [!known('observation'),'Eine belegte Fahrt ist noch kein aktueller Aufenthaltsnachweis.','Ortiz kann die Holloway-Werkstatt verdeckt überprüfen.','locations'],
 [!known('rescue'),'Die Beamten haben das Kind gefunden und befreien es jetzt.','Die Rettung läuft bereits. Im Einsatzchat sehen Sie die nächste Rückmeldezeit.','observation'],
 [!known('scene'),'Für eine belastbare Aufklärung fehlen gesicherte Spuren.','Ortiz soll das Büro und Mercers Hemd sichern.','mercer'],
 [!known('lab'),'Eine Behauptung über die Herkunft des Flecks ist überprüfbar.','Voss kann Hemd, Schrank und Vergleichsproben abgleichen.','scene'],
 [!known('medical'),'Die verletzte Zeugin hat noch keine eigene Stimme bekommen.','Shaw kann Naomi nach ärztlicher Freigabe befragen lassen.','harbor'],
 [!known('accounts'),'Der Streit im Büro hatte einen überprüfbaren Anlass.','Park soll die gesicherten Rechnungen mit den Lieferungen abgleichen.','scene'],
 [!known('child'),'Jamie darf nach Versorgung und Pause selbst berichten.','Shaw koordiniert das geschützte Gespräch.','rescue'],
 [!known('device'),'Die falsche Nachricht benötigt einen Geräteabgleich.','Park kann das sichergestellte Telefon auswerten.','rescue'],
 [!known('arrest')&&!known('fugitive'),'Mercers aktueller Aufenthaltsstatus ist offen.','Beauftragen Sie Ortiz mit der Festnahme. Bei einer Flucht wird die Fahndung dokumentiert.','rescue'],
 [!known('family'),'Die Familie sollte nicht mit ungeprüften Verdächtigungen im Fall bleiben.','Lassen Sie Freunde und Vater abklären.','mother'],
 [!known('conflict'),'Rachels erste Aussage lässt eine persönliche Frage offen.','Fragen Sie über Ortiz nach dem Anlass für die abgesagte Abholung.','phone']
 ];const stageJobs=[null,'harbor','mercer','camera','locations','observation','rescue','scene','lab','medical','accounts','child','device','arrest','family','conflict'];
 const step=stages.find((s,i)=>s[0]&&(!stageJobs[i]||(!flow.tasks[stageJobs[i]]&&!missing(stageJobs[i]).length)));
 if(step)return [step[flow.hintLevel%2?1:2]+(pending().length?' Es laufen außerdem Aufträge; Rückmeldungen lassen sich vorspulen.':''),known(step[3])?[step[3]]:[]];
 const waiting=pending()[0];
 if(waiting)return ['Die noch fehlenden Rückmeldungen sind bereits beauftragt. Als Nächstes: '+jobTypes[waiting[0]].title+' bis '+hhmm(waiting[1].due)+'. Wenn Sie die vorhandenen Unterlagen geprüft haben, können Sie zur nächsten Rückmeldung vorspulen.',[]];
 return ['Ordnen Sie auf dem Board die Belege zu einer begründeten Rekonstruktion. Für den Abschluss müssen Angriff, Fahrt, Verdeckung und Motiv zusammenpassen.',['board']];}
function proposeConfrontation(){if(!known('mercer')){reply('Mercer wurde noch nicht regulär befragt. Wir brauchen zuerst seine eigene Aussage.');return;}if(known('arrest')){interrogate();return;}if(flow.warned){reply('Mercer hat das freiwillige Gespräch nach der Konfrontation beendet. Sein Aufenthaltsort muss über den Außendienst geklärt werden.');return;}if(known('rescue')){reply('Jamie ist in Sicherheit. Klären Sie jetzt über Ortiz die Festnahme. Danach können wir ein dokumentiertes Gespräch führen.');return;}flow.decision='confront';reply('Ein früher Vorhalt kann Mercer warnen. Jamie ist noch nicht gesichert, und Mercer ist derzeit nur freiwillig hier. Möchten Sie ihn trotzdem jetzt mit dem Verdacht konfrontieren? Nutzen Sie die Entscheidung unter dem Chat.');}
function confirmConfrontation(){flow.decision='';flow.warned=true;recordMessage('ellis','Ellis legt Mercer den Widerspruch vor. Er wird knapp: „Dann irrt Holly sich.“ Er beendet das freiwillige Gespräch. Kurz darauf meldet Ortiz, dass Mercer das Foyer verlassen hat. Die Suche nach Jamie läuft weiter.');flow.clock+=5;finishJobs();renderChat();save();}
function interrogate(){if(!known('arrest')){reply('Für eine Befragung in Gewahrsam fehlt die Festnahme.');return;}if(known('confession')){reply('Seine Einlassung ist bereits protokolliert.',['confession']);return;}if(!['lab','child','camera','accounts'].every(known)){reply('Wir sollten ihm konkrete Befunde vorhalten. Für dieses Gespräch fehlen noch Teile von Laborvergleich, Jamies Aussage, Fahrzeugauswertung oder Rechnungsprüfung. Schweigen oder Nervosität ersetzen keinen Beleg.');return;}addPaper('confession');reply('Ich habe ihm die belegten Punkte einzeln vorgehalten. Seine Einlassung liegt als A-007 vor. Sie ergänzt die Beweise; ein Geständnis ist für Ihren Fallabschluss nicht zwingend erforderlich.',['confession']);notifyPaper('confession');}
function handleInput(raw){const q=raw.toLocaleLowerCase('de-DE').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 if(/\b(nicht|kein|keinen|keine|stopp|stop|abbrechen)\b/.test(q)&&/schick|befrag|auftrag|festnehm|verhaft|konfront|sicher/.test(q)){reply('Kein neuer Auftrag ausgelöst. Laufende Aufträge bleiben bestehen. Bitte nennen Sie eine eindeutige gewünschte Handlung.');return;}
 if(/hilfe|tipp|hinweis|wie.*weiter|was.*tun/.test(q)){reply(...hint());return;}
 if(/status|wie lange|wann.*(fertig|bericht)|warte/.test(q)){reply(pending().length?pending().map(([id,t])=>jobTypes[id].title+' bis '+hhmm(t.due)).join(' · '):'Keine laufenden Aufträge. Unter „Aufträge vorbereiten“ finden Sie die aus Ihrem Wissensstand möglichen Anfragen.');return;}
 if(typeof answerKnownQuestion==='function'&&answerKnownQuestion(q))return;
 if(/konfront|vorhalt|widerspruch.*ansprech|beweise.*vorleg|gestandnis/.test(q)){if(contact!=='ellis'){reply('Ellis führt den Vorhalt. Wählen Sie sie im Chat; ein Beweisvorhalt erfolgt nicht automatisch.');return;}proposeConfrontation();return;}
 if(/festnehm|nehm.*fest|verhaft|festsetz|gewahrsam/.test(q)){startJob('arrest');return;}
 if(/rett|befrei|zugriff|raushol/.test(q)){startJob('rescue');return;}
 if(/blut|dna|hemd.*(vergleich|untersuch)|spur.*vergleich/.test(q)){if(/sicher|holen|einsammel/.test(q)&&!/vergleich|analys|untersuch/.test(q)){startJob('scene');return;}startJob('lab');return;}
 if(/rechnung|buchhalt|lieferung|betrug|veruntreu/.test(q)){if(/sicher/.test(q))startJob('scene');else startJob('accounts');return;}
 if(/kamera|video|apotheke/.test(q)){startJob('camera');return;}
 if(/telefon|handy|gerat/.test(q)&&/auswert|untersuch|sicher/.test(q)){startJob('device');return;}
 if(/holloway|werkstatt|14b/.test(q)){if(/schick|team|pruf.*ort|durchsuch|uberpruf|fahr.*hin|observ|verdeckt/.test(q))startJob('observation');else startJob('locations');return;}
 if(/fahrzeug|transporter|route|nutzungsort|adress|kennzeichen/.test(q)){startJob('locations');return;}
 if(/naomi|krankenhaus|verletzte/.test(q)&&!/blut/.test(q)){startJob('medical');return;}
 if(/jamie|kind|junge/.test(q)&&/befrag|sprech|aussage.*aufnehm/.test(q)){startJob('child');return;}
 if(/mutter|rachel/.test(q)&&/morgen|streit|nachricht|abhol|ton|absag|warum/.test(q)){startJob('conflict');return;}
 if(/familie|freund|vater|owen|luis|aaron/.test(q)&&/frag|pruf|sprech|ruf|alibi|kontakt/.test(q)){startJob('family');return;}
 if(/spur|hemd|buro|zeichenheft/.test(q)&&/sicher|pruf|untersuch|abhol/.test(q)){startJob('scene');return;}
 if(/mercer|daniel/.test(q)&&/befrag|frag|sprech|alibi|zeit/.test(q)){startJob('mercer');return;}
 if(/harbor|zentrum|kurs|team/.test(q)&&/schick|pruf|such|fahr|befrag|frag|ermitt/.test(q)){startJob('harbor');return;}
 if(/aussage|bericht|protokoll|wer ist|was wissen/.test(q)){let id=/mutter|rachel/.test(q)?'mother':/mercer|daniel/.test(q)?'mercer':/naomi/.test(q)?'medical':/jamie/.test(q)?'child':null;if(id){reply(known(id)?papers[id].summary:'Dazu liegt noch keine gesicherte Aussage vor.',known(id)?[id]:[]);return;}}
 if(/fall.*(abschlie|losen)|abschluss/.test(q)){reply('Den Abschluss bereiten Sie auf dem Ermittlungsboard vor. Belegen Sie Ihre Rekonstruktion und reichen Sie den Abschlussbericht ein.',['board']);return;}
 if(/hallo|danke|verstanden|guten tag/.test(q)){reply('Ich bin erreichbar, Detective. Unter „Aufträge vorbereiten“ können Sie passende Formulierungen einsetzen und anschließend selbst senden.');return;}
 reply('Ich kann die Frage noch nicht sicher zuordnen. Es wurde nichts ausgelöst. Nennen Sie Person oder Quelle und die gewünschte Handlung. „Aufträge vorbereiten“ zeigt verständliche Formulierungen für den bisherigen Ermittlungsstand.');
}
function sendInvestigationMessage(){const input=root.querySelector('#gh-example-message'),text=input.value.trim();if(!text){input.focus();return;}recordMessage(contact,text,'me');drafts[contact]='';handleInput(text);renderChat();renderDesign();save();}
