function renderInvestigationChat(){setMood();const input=root.querySelector('#gh-example-message'),selection=[input.selectionStart,input.selectionEnd],wasFocused=document.activeElement===input,priorArea=root.querySelector('.gh-messages'),priorScroll=priorArea.scrollTop,nearBottom=priorArea.scrollHeight-priorArea.scrollTop-priorArea.clientHeight<60;const c=contacts[contact];root.querySelector('[data-avatar]').textContent=c.avatar;root.querySelector('[data-contact-name]').textContent=c.name;root.querySelector('[data-contact-role]').textContent=c.role;root.querySelectorAll('[data-contact]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.contact===contact)));const area=root.querySelector('.gh-messages');area.replaceChildren(message(c.intro,c.name));if(contact==='ellis')makeRefs(area.lastChild,['mother','phone']);for(const entry of flow.journals[contact]){const n=message(entry.text,entry.who==='me'?'Sie':c.name);n.querySelector('.gh-message-label span').textContent=hhmm(entry.at);makeRefs(n,entry.refs);area.append(n);}root.querySelector('#gh-example-message').value=drafts[contact];root.querySelector('.gh-send').textContent='Senden ↑';root.querySelector('.gh-send').disabled=false;renderFlowChrome();renderDecision();area.scrollTop=nearBottom?area.scrollHeight:priorScroll;if(wasFocused)input.setSelectionRange(...selection);}
