function openPaper(id){if(!known(id))return;flow.doc=id;for(const n of flow.inbox||[])if(n.refs.includes(id))n.read=true;renderInbox();if(!flow.read.includes(id))flow.read.push(id);if(id==='mother'&&onboarding.step==='read'){onboarding.step='reading';renderGuide();}renderRecord();open('records');if(root.querySelector('.gh-flow-notification').dataset.doc===id)root.querySelector('.gh-flow-notification').hidden=true;save();}
function prepareOrder(id){const j=jobTypes[id];if(!j)return;contact=j.channel;drafts[contact]=j.command;renderChat();open('chat');root.querySelector('#gh-example-message').focus();}
