function inspectPoint(id){
 const observations={
 'phone-last':['16:03 · Ein unbenannter Freund','In den vorherigen Nachrichten nennt Jamie Orte und fragt wegen der Abholung nach. Die letzte Nachricht nennt keinen Namen und sagt die Abholung ab. Das ist ein Anlass für eine Rückfrage, kein Nachweis, wer getippt hat.'],
 'scene-blood':['E-002 · Spur an der Schrankkante','Ein dunkler Fleck an der Kante. Die Spurensicherung hat einen Blutabstrich gesichert. Die Lage passt zur gemeldeten Kopfverletzung; die Herkunft ist zu untersuchen.'],
 'scene-chair':['Umgestürzter Stuhl','Der Stuhl liegt seitlich neben dem Schrank. Sie können aus der Lage allein nicht entscheiden, ob Naomi gestürzt oder gestoßen worden ist.'],
 'scene-notebook':['E-004 · Der Roboter mit dem schiefen Rad','Jamies Name steht auf dem Heft. Grant hat es Mercer gegeben. Damit ist nachvollziehbar, warum Jamie zum Verwaltungsbüro zurückging. Sein weiterer Weg bleibt offen.'],
 'scene-bills':['E-005 · Markierte Rechnungen','Naomi hat zwei Lieferungen mit denselben Positionen markiert. Daneben steht: „D. fragen / Original bis Freitag / Vorstand informieren“. Ein Lieferantenabgleich kann die Frage klären.'],
 'invoice-original':['NG-1847 · Original','Die Lieferung und das Konto des Lieferanten sind dokumentiert. Markieren Sie den zweiten Beleg für den Abgleich.'],
 'invoice-duplicate':['NG-1847-B · Zweite Zahlung','Gleiche Fenster und gleiches Lieferdatum, aber ein anderes Zahlungskonto. Park kann beim Lieferanten klären, ob es eine zweite Lieferung gab.']};
 if(!observations[id])return;markInspected(id);materialDetail(...observations[id]);root.querySelectorAll('[data-inspect]').forEach(b=>b.setAttribute('aria-pressed',String(flow.inspected.includes(b.dataset.inspect))));
}
function compareSamples(){
 const a=root.querySelector('[data-sample=a]').value,b=root.querySelector('[data-sample=b]').value;
 if(a===b){materialDetail('Zwei verschiedene Proben wählen','Eine Probe mit sich selbst zu vergleichen beantwortet die Herkunftsfrage nicht.');return;}
 if(!known('lab')){contact='lab';renderChat();startJob('lab');renderChat();save();materialDetail('Auftrag an Voss','Der Blutspurenvergleich umfasst die beiden Spuren und beide Vergleichspersonen. Er läuft mehrere Stunden Fallzeit. Sie können währenddessen die Suche fortsetzen.');return;}
 const naomi=[[15,18],[17,18],[12,14],[11,12],[13,17],[29,31],[22,24],[8,11]],mercer=[[14,16],[16,19],[11,13],[9,13],[12,18],[28,32],[21,25],[8,10]];
 const profile={cabinet:naomi,shirt:naomi,naomi,mercer};
 for(const side of ['a','b']){const card=root.querySelector('[data-sample='+side+']').parentElement;card.querySelector('.gh-profile-plot')?.remove();card.append(profileTrace(profile[side==='a'?a:b],side));}
 const match=JSON.stringify(profile[a])===JSON.stringify(profile[b]);materialDetail(match?'Untersuchte Merkmale stimmen überein':'Mercer als Spurenursprung ausgeschlossen',match?'Die untersuchten Blutspuren passen zu Naomis Vergleichsprofil. Das bestätigt den dokumentierten Laborbefund. Ein möglicher Kontakt bei einer Hilfeleistung ist anhand weiterer Beweise zu prüfen.':'Die untersuchten Blutspuren passen nicht zu Mercers Profil. Seine Erklärung „eigenes Blut“ ist mit diesem Befund nicht vereinbar.');markInspected('lab-'+[a,b].sort().join('-'));
}
function profileTrace(alleles,side){
 const names=['D3S1358','vWA','D8S1179','D16S539','D18S51','D21S11','FGA','TPOX'],ranges=[[11,21],[13,22],[8,17],[6,16],[9,21],[25,35],[18,28],[5,14]],ns='http://www.w3.org/2000/svg';
 const plot=el('div',undefined,'gh-profile-plot');plot.append(el('small','L-001 · Ausschnitt des untersuchten Profils'));
 for(const[locus,pair]of alleles.entries()){
  const row=el('div',undefined,'gh-str-locus');row.append(el('strong',names[locus]));const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 270 64');svg.setAttribute('role','img');svg.setAttribute('aria-label',names[locus]+' · Allele '+pair.join(' und '));
  const[low,high]=ranges[locus],position=n=>18+(n-low)/(high-low)*234;let d='';
  for(let x=12;x<=258;x+=1.5){let height=0;for(const[i,allele]of pair.entries())height+=(i?30:40)*(side==='a'?1:.87)*Math.exp(-.5*((x-position(allele))/2.4)**2);d+=(x===12?'M':'L')+x.toFixed(1)+','+(46-height).toFixed(2)+' ';}
  const trace=document.createElementNS(ns,'path');trace.setAttribute('d',d);trace.setAttribute('fill','none');trace.setAttribute('stroke',side==='a'?'#a2d2db':'#cfb994');trace.setAttribute('stroke-width','1.6');svg.append(trace);
  for(const allele of pair){const label=document.createElementNS(ns,'text');label.setAttribute('x',position(allele));label.setAttribute('y','61');label.setAttribute('text-anchor','middle');label.setAttribute('fill','#bacad0');label.setAttribute('font-size','10');label.textContent=allele;svg.append(label);}row.append(svg);plot.append(row);
 }
 plot.append(el('small','Vergleichen Sie die Positionen. Der vollständige Befund steht in L-001.'));return plot;
}
const witnessNames={rachel:'Rachel Bennett',mercer:'Daniel Mercer',naomi:'Naomi Price'};
const witnessQuestions={
 rachel:[['pickup','Was war für die Abholung vereinbart?'],['friends','Wen meint Jamie mit einem Freund?'],['morning','Gab es heute Morgen etwas zwischen Ihnen?']],
 mercer:[['time','Wann sind Sie heute abgefahren?'],['jamie','Wie gut kennen Sie Jamie?'],['shirt','Warum haben Sie Ihr Hemd gewechselt?']],
 naomi:[['bills','Warum wollten Sie mit Mercer sprechen?'],['injury','Woran erinnern Sie sich vor der Verletzung?'],['workshop','Welche Werkstatt benutzt Mercer?']]
};
function openInterview(id){if(!witnessNames[id]||(id==='mercer'&&!known('mercer'))||(id==='naomi'&&!known('medical')))return;interviewId=id;inspectionFocus=document.activeElement;root.querySelector('.gh-material-desk').hidden=true;root.querySelector('.gh-interview-desk').hidden=false;root.querySelector('[data-interview-title]').textContent=witnessNames[id];root.querySelector('[data-interview-room]').textContent=id==='naomi'?'GREYHAVEN GENERAL · FREIGEGEBENES GESPRÄCH':id==='rachel'?'HARBOR HOUSE · RUHIGER NEBENRAUM':known('arrest')?'GPD · BEFRAGUNGSRAUM 02':'HARBOR HOUSE · FREIWILLIGES GESPRÄCH';
 root.querySelector('[data-interview-image]').src=inspectionAssets[id+'-neutral'];root.querySelector('[data-interview-image]').alt=witnessNames[id]+' während des Gesprächs';
 if(!flow.interviews[id])flow.interviews[id]=[];renderWitness();root.querySelector('[data-interview-close]').focus();
}
function renderWitness(){const messages=root.querySelector('[data-interview-messages]');messages.replaceChildren();for(const entry of flow.interviews[interviewId]||[]){const p=el('p',entry.text);p.dataset.speaker=entry.who;messages.append(p);}if(!messages.childNodes.length)messages.append(el('p',interviewId==='naomi'?'Shaw: Naomi ist für ein kurzes Gespräch freigegeben. Wir machen Pause, sobald sie ermüdet.':interviewId==='mercer'?'Ellis führt Ihre Fragen vor Ort weiter. Legen Sie konkrete Belege vor, wenn Sie einen Widerspruch klären wollen.':'Ortiz sitzt bei Rachel. Sie hört Ihre Fragen über den Ermittlungsanschluss.'));messages.scrollTop=messages.scrollHeight;root.querySelector('[data-interview-questions]').replaceChildren(...witnessQuestions[interviewId].map(([id,label])=>action(label,'witnessquestion',id)));const evidence=root.querySelector('[data-interview-evidence]');evidence.replaceChildren(...flow.known.filter(id=>['phone','conflict','harbor','camera','lab','accounts','child'].includes(id)).map(id=>action(papers[id].code+' · '+papers[id].title,'witnessevidence',id)));}
function witnessReply(question,answer,emotion='neutral'){const list=flow.interviews[interviewId];list.push({who:'detective',text:question},{who:'witness',text:answer});if(!completeTranscripts)flow.interviews[interviewId]=list.slice(-16);root.querySelector('[data-interview-image]').src=inspectionAssets[interviewId+'-'+emotion];renderWitness();save();}
function askWitness(id,raw){const name=interviewId;const label=raw||witnessQuestions[name].find(([key])=>key===id)?.[1]||'Rückfrage';
 const answers={
 rachel:{pickup:'„Um vier, am Haupteingang. Er wollte mir seinen Roboter zeigen. Ich hatte Käse für die Nudeln gekauft. Ich weiß nicht, warum ich Ihnen das erzähle. Das war einfach ein ganz normaler Nachmittag.“',friends:'„Luis oder Aaron. Aber dann schreibt er mir, zu wem er geht. Ich kenne ihre Eltern. Er sagt nicht einfach: ein Freund.“',morning:known('conflict')?'„Er wollte zu Owen. Ich habe gesagt: Dann geh doch. Ich wollte nicht, dass er wirklich geht. Mittags war die Abholung doch ausgemacht. Bitte sagen Sie mir nicht, dass er deshalb verschwunden ist.“':'Ortiz: Dazu ist noch keine Nachbefragung aufgenommen. Ich frage Rachel in Ruhe; die Rückmeldung erscheint im Chat und in A-002.'},
 mercer:{time:'„Fünf vor halb vier. Ich hatte auf die Uhr gesehen. Material besorgen. Viertel nach vier war ich wieder hier. Welchen Laden? Ich habe nichts Passendes gefunden. Müssen wir das jetzt machen? Der Junge ist weg.“',jamie:'„Er kennt mich. Wenn an seinem Modell etwas kaputt war, habe ich ihm geholfen. Er hat den Roboter die ganze Woche nicht aus der Hand gelegt. Nach dem Kurs habe ich ihn heute nicht gesehen.“',shirt:'„Am Blech geschnitten. Ich hatte Blut am Hemd und wollte es wechseln. Ortiz hat es jetzt. Sie haben alles, was Sie brauchen. Haben Sie schon etwas von Jamie gehört?“'},
 naomi:{bills:'„Eine Fensterlieferung. Zwei Rechnungen. Für diese Fenster haben die Kinder Kuchen verkauft. Ich wollte Daniel erst fragen, bevor ich zum Vorstand gehe. Vielleicht war es ein Fehler. Ich wollte, dass es ein Fehler ist.“',injury:'„Ich habe das Papier festgehalten. Daniel stand vor mir. An der Tür war ein Kind. Dann die Kante am Schrank. Ich weiß nicht mehr, wie ich da hingekommen bin. Bitte schreiben Sie nichts dazu, was ich nicht gesagt habe.“',workshop:'„Die alte Holloway-Werkstatt. Er hat unsere Bühnenbilder dort repariert. Den Schlüssel hat er noch. Die Adresse steht bei den Lieferstellen. Ich kann mich gerade nicht an die Nummer erinnern.“'}
 };
 if(!answers[name][id]){witnessReply(label,'Die Befragerin: Bitte beziehen Sie die Frage auf die Abholung, den Zeitablauf, die Verletzung oder einen konkreten vorliegenden Beleg. Dazu kann ich noch keine belastbare Antwort weitergeben.');return;}
 if(name==='rachel'&&id==='morning'&&!known('conflict')){contact='ortiz';startJob('conflict');renderChat();}
 witnessReply(label,answers[name][id],id==='morning'||id==='injury'?'strained':id==='time'?'guarded':'neutral');
}
function presentWitnessEvidence(id){if(!known(id))return;
 if(interviewId==='mercer'){
  if(!known('arrest')){root.querySelector('.gh-interview-desk').hidden=true;contact='ellis';renderChat();open('chat');proposeConfrontation();renderChat();save();return;}
  const responses={harbor:'„Holly muss sich irren. Ich war da schon unterwegs.“',camera:'„Ja. Das bin ich. Ich habe ihn mitgenommen. Er wollte mit. Das ist alles.“',lab:'„Ich habe Naomi vielleicht berührt. Ich wollte nachsehen ... Das vorhin, mit meinem Finger. Ich wollte Ihnen keine Geschichte erzählen.“',accounts:'„Ich wollte das zurückzahlen. Bevor jemand die Belege sieht. Es hätte keiner merken müssen.“',child:'Mercer blickt lange auf den Tisch. „Er vertraut mir“, sagt er. Ellis: „Genau deshalb müssen Sie uns erklären, warum er aus dem Raum nicht herauskam.“'};
  witnessReply(papers[id].code+' vorlegen',responses[id]||'Ellis: Dieser Beleg allein beantwortet unsere Frage an Mercer noch nicht.','guarded');
 }else if(interviewId==='rachel'&&id==='phone')askWitness('morning','Warum hat Jamie die Abholung so abgesagt?');
 else if(interviewId==='naomi'&&id==='accounts')askWitness('bills','Diese Rechnung wurde nicht vom Lieferanten ausgestellt. Erkennen Sie sie?');
 else witnessReply(papers[id].code+' vorlegen','Die Befragerin: Dazu kann die Person keine eigene sichere Beobachtung beitragen. Wir ergänzen keine Vermutung als Aussage.');
}
function answerKnownQuestion(q){
 if(!/^(wer|was|wo|wann|warum|wieso|wie|kennt|wissen|ist|hat|kannst du mir|konnen sie mir)\b/.test(q)||/bitte.*(befrag|untersuch|pruf)|nehmt|schickt/.test(q))return false;
 let id=/naomi/.test(q)?'medical':/mercer|daniel/.test(q)?'mercer':/mutter|rachel/.test(q)?'mother':/blut|dna|hemd/.test(q)?'lab':/nachricht/.test(q)?'phone':/werkstatt/.test(q)?'locations':/jamie/.test(q)?known('rescue')?'rescue':'mother':null;
 const facts=[
  [/wer.*(getippt|geschrieben)|verfasser|nachricht.*(echt|gefalscht)/,['device','child'],'Die Geräteauswertung belegt die Nachricht auf Jamies Telefon. Zusammen mit seiner geschützten Aussage ist nachvollziehbar, dass Mercer sie geschrieben hat. Der Schreibstil allein hätte das nicht bewiesen.','Sender und Inhalt stehen auf Rachels Aufnahme. Wer getippt hat, ist noch nicht nachgewiesen.'],
  [/wo.*jamie|jamie.*(standort|aufenthalt|gefunden)/,'rescue','Jamie ist befreit und wird versorgt. Die geschützte Befragung erfolgt nach der medizinischen Freigabe.','Jamies aktueller Aufenthaltsort ist noch nicht bestätigt. '+(known('locations')?'Der Transporter führt zur Holloway-Werkstatt. Ortiz muss dort vor Ort nachsehen.':known('camera')?'Die Kamera zeigt Mercer mit einer kleineren Person im Transporter. Ihr Gesicht ist verdeckt; Jamie ist dadurch noch nicht sicher identifiziert. Die Aufnahme liefert eine Fahrtspur, keinen bestätigten aktuellen Standort.':'Ausgangspunkt bleibt das Harbor House.')],
  [/warum.*(hemd|umgezogen)|wessen.*blut|blut.*(herkunft|ursprung|stammt)/,'lab','Die untersuchten Spuren passen zu Naomis Vergleichsprofil und nicht zu Mercers. Seine Erklärung „eigenes Blut vom Finger“ ist widerlegt. Wie ihr Blut auf das Hemd gelangte, muss mit Aussagen und weiteren Spuren geklärt werden.','Mercer erklärt den Fleck mit einer eigenen Schnittverletzung. Das ist seine Darstellung. Ohne Laborbefund ist die Herkunft offen.'],
  [/wann.*(abgefahren|abfahrt)|zeit.*widerspruch|widerspruch.*zeit/,['camera','mercer','harbor'],'Die abgeglichene Apothekenkamera zeigt die Abfahrt um 15:42. Mercer nannte 15:25. Grant sah Jamie etwa 15:35 bei ihm. Die unabhängige Aufnahme klärt die Abfahrtszeit.','Eine überprüfte Abfahrtszeit ergibt sich aus einer unabhängigen Quelle. Wir müssen die vorhandenen Aussagen mit der gesicherten Kamera vergleichen.'],
  [/warum.*(mutter|rachel).*(verschwiegen|streit|erzahlt)|rachel.*(verschwiegen|gelogen)/,'conflict','Rachel schämte sich für ihren Satz beim Frühstück und fürchtete, wir würden weniger nach Jamie suchen. Mittags war die Abholung trotzdem vereinbart. Der Streit belegt keine Entführung durch sie.','Die Erstaufnahme ist eine kurze Meldung unter Zeitdruck. Fragen zum Nachrichtenverlauf und Familienalltag können wir über Ortiz stellen.'],
  [/rechnung.*(falsch|doppelt|konto)|warum.*(geld|rechnung)|wie.*(betrug|rechnung)/,'accounts','Der Lieferant bestätigt eine Fensterlieferung. Das zweite Konto gehört nicht zu ihm. Zusammen mit Naomis Gespräch ergibt sich ein Vertuschungsmotiv. Das Motiv allein identifiziert keinen Täter.','Ähnliche Rechnungen begründen einen Prüfauftrag. Erst der Lieferantenabgleich kann eine zweite Lieferung oder eine abweichende Zahlung klären.'],
  [/wer.*(tater|morder|entfuhrer)|ist.*mercer.*(schuldig|tater)|mercer.*(bewiesen|uberfuhrt)/,'child','Jamies Aussage ist ein konkreter Belastungsbeleg. Für die vollständige Rekonstruktion brauchen wir außerdem die Fahrt, den Blutbefund und den Rechnungsabgleich. Prüfen Sie diese Begründung auf der Beweistafel.','Die Täterschaft ist noch nicht ausreichend belegt. Ein auffälliges Verhalten oder eine einzelne falsche Angabe ersetzt die Beweiskette nicht.']
 ];
 for(const[pattern,source,established,unresolved]of facts)if(pattern.test(q)){const needs=Array.isArray(source)?source:[source],available=needs.every(known);reply(available?established:unresolved,available?needs:[]);return true;}
 if(!id)return false;
 if(!known(id)){reply('Dazu liegt mir noch keine gesicherte Rückmeldung vor. '+(id==='medical'?'Shaw kann das Gespräch nach ärztlicher Freigabe koordinieren.':id==='lab'?'Voss benötigt zunächst gesicherte Spuren und einen Vergleichsauftrag.':'Wir müssen die betreffende Person oder Quelle erst überprüfen.'));return true;}
 reply(papers[id].summary+' '+(id==='lab'?'Der Befund sagt für sich nichts über den Zeitpunkt oder die Art der Übertragung.':id==='mercer'?'Das ist seine Aussage. Vergleichen Sie sie mit unabhängigen Beobachtungen.':''),[id]);return true;
}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.material)openMaterial(b.dataset.material);if(b.dataset.inspect)inspectPoint(b.dataset.inspect);if(b.dataset.compare)compareSamples();if(b.dataset.materialorder){const id=b.dataset.materialorder;if(known(id))openPaper(id);else prepareOrder(id);root.querySelector('.gh-material-desk').hidden=true;}if(b.dataset.interview)openInterview(b.dataset.interview);if(b.dataset.witnessquestion)askWitness(b.dataset.witnessquestion);if(b.dataset.witnessevidence)presentWitnessEvidence(b.dataset.witnessevidence);if(b.hasAttribute('data-material-close')||b.hasAttribute('data-interview-close')){root.querySelector('.gh-material-desk').hidden=true;root.querySelector('.gh-interview-desk').hidden=true;inspectionFocus?.focus();}});
root.querySelector('[data-interview-form]').addEventListener('submit',e=>{e.preventDefault();const input=root.querySelector('#gh-witness-question'),raw=input.value.trim();if(!raw)return;const q=raw.toLowerCase();const id=interviewId==='rachel'?/morgen|streit|nachricht/.test(q)?'morning':/freund|luis|aaron/.test(q)?'friends':/abhol|vier|uhr|vereinbar/.test(q)?'pickup':'unknown':interviewId==='mercer'?/hemd|blut|schnitt|umgezogen/.test(q)?'shirt':/zeit|wann|fahrt|abfahr|einkauf/.test(q)?'time':/jamie|junge|modell|kennt/.test(q)?'jamie':'unknown':/rechnung|papier|vorstand|streit/.test(q)?'bills':/werkstatt|holloway|schlussel/.test(q)?'workshop':/verletz|erinner|stoss|schrank|kind/.test(q)?'injury':'unknown';askWitness(id,raw);input.value='';});
root.addEventListener('keydown',e=>{const modal=[root.querySelector('.gh-material-desk'),root.querySelector('.gh-interview-desk')].find(n=>!n.hidden);if(!modal||cinemaSession)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();modal.hidden=true;inspectionFocus?.focus();}if(e.key==='Tab'){const nodes=[...modal.querySelectorAll('button,input,textarea,select,summary')].filter(n=>!n.disabled&&n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});

function showSaveError(){
 let panel=root.querySelector('.gh-save-error');if(panel)return;
 panel=el('div',undefined,'gh-save-error');panel.setAttribute('role','alert');panel.append(el('strong','Spielstand konnte nicht gespeichert werden.'),el('p','Ihre Ermittlung bleibt geöffnet. Prüfen Sie den freien Speicherplatz und versuchen Sie es erneut.'),action('Erneut speichern','retrySave','true'));root.append(panel);
}
root.addEventListener('click',e=>{if(e.target.closest('[data-retry-save]'))save();});
window.greyhavenNative?.onCloseRequested(async()=>{if(await save()===false){await window.greyhavenNative.cancelClose();return;}await window.greyhavenNative.finishClose();});
function renderProfiles(){
 const boot=window.greyhavenProfiles?.get();if(!boot)return;
 const panel=root.querySelector('[data-profile-list]');panel.replaceChildren();
 for(const p of boot.profiles){const b=action('Detective '+p.name+(p.completed?.includes('tutorial-gh01')?' · Tutorial abgeschlossen':p.hasSave?' · Ermittlung fortsetzen':' · Bereit'),'profile',p.id);b.setAttribute('aria-pressed',String(p.id===boot.active));panel.append(b);}
 const episodes=root.querySelector('[data-episode-grid]');episodes.replaceChildren();const p=boot.profiles.find(p=>p.id===boot.active),completed=p?.completed||[];
 const tutorial=action('TUTORIAL · Nicht nach Hause gekommen'+(completed.includes('tutorial-gh01')?' · Abgeschlossen':' · Installiert'),'episode','tutorial-gh01');episodes.append(tutorial);
 for(let i=1;i<=13;i++){const predecessor=i===1?'tutorial-gh01':'s1-e'+String(i-1).padStart(2,'0'),unlocked=completed.includes(predecessor);const card=el('article',undefined,'gh-episode-card');card.dataset.locked=String(!unlocked);card.append(el('span',unlocked?'○ FREIGESCHALTET':'🔒 GESPERRT'),el('h3','Episode '+String(i).padStart(2,'0')),el('p',unlocked?'Wird mit einem kommenden Episodenupdate veröffentlicht.':'Schließen Sie '+(i===1?'den Tutorialfall':'Episode '+String(i-1).padStart(2,'0'))+' ab, um diesen Fall freizuschalten.'));episodes.append(card);}
}
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.profile){if(await save()===false)return;let boot;try{boot=await window.greyhavenProfiles.select(b.dataset.profile);}catch{showSaveError();return;}if(boot.reloading)return;ownSnapshots.clear();if(boot.state){restore(boot.state);savedAvailable=true;}else{Object.assign(flow,freshFlow());Object.assign(onboarding,{name:boot.profiles.find(p=>p.id===boot.active)?.name||'Morgan',started:false,step:'done'});savedAvailable=false;}applyName();showFront('menu');renderProfiles();}if(b.dataset.frontAction==='episodes'){showFront('episodes');renderProfiles();}if(b.dataset.episode==='tutorial-gh01'){if(savedAvailable)enterDesktop();else showFront('name');}if(b.dataset.frontAction==='exit'&&window.greyhavenNative){if(await save()===false)return;window.greyhavenProfiles.quit();}if(b.dataset.launcher&&window.greyhavenNative){if(await save()===false)return;window.greyhavenNative.launcher();}});
window.addEventListener('greyhaven:profiles',()=>renderProfiles());


const onboarding={name:'Morgan',started:false,step:'done'};
let savedAvailable=false,frontPanel='menu';
const nameNodes=[];
function initFrontDoor(){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const n=walker.currentNode;if(n.parentElement.closest('script,style,.gh-messages'))continue;if(/Detective Morgan/i.test(n.textContent))nameNodes.push({node:n,template:n.textContent});}applyName();showFront('menu');const pendingName=window.greyhavenProfiles?.get().newProfileName;if(pendingName){root.querySelector('#gh-detective-name').value=pendingName;queueMicrotask(()=>root.querySelector('#gh-new-game button').click());}}
function applyName(){for(const item of nameNodes)item.node.textContent=item.template.replace(/Detective Morgan/gi,()=> 'Detective '+onboarding.name);contacts.ellis.intro='Detective '+onboarding.name+', die Erstaufnahme von Rachel Bennett und der gesicherte Nachrichtenverlauf liegen in der Fallakte. Ortiz koordiniert den Außendienst. Ich bleibe erreichbar; fragen Sie mich ausdrücklich, wenn Sie einen Tipp möchten.';root.querySelector('[data-brief-greeting]').textContent='„Detective '+onboarding.name+', Sie übernehmen die Ermittlungsleitung. Mara Ellis begleitet Sie. Unsere ersten Unterlagen liegen bereit.“';}
function refreshMenu(){const menu=root.querySelector('.gh-front-buttons');menu.prepend(menu.querySelector('[data-front-action=new]'),menu.querySelector('[data-front-action=load]'));root.querySelector('[data-front-action="load"]').disabled=!savedAvailable;root.querySelector('[data-save-label]').textContent=savedAvailable?'Letzter Stand: Detective '+onboarding.name+' · '+hhmm(flow.clock)+' · Nicht nach Hause gekommen':'Noch kein Spielstand vorhanden.';root.querySelector('[data-new-warning]').textContent='Ein neuer Detective bekommt ein eigenes Profil. Ihre anderen Ermittlungsstände bleiben gespeichert.';renderProfiles();}
