root.addEventListener('keydown',e=>{
 const sound=root.querySelector('.gh-sound-panel');
 if(e.key==='Escape'){
  e.preventDefault();
  if(!sound.hidden){sound.hidden=true;returnFocus?.focus();return;}
  if(cinemaSession)cinemaFinish();root.querySelector('.gh-inbox').hidden=true;return;
 }
 if(!cinemaSession?.produced)return;
 if(e.code==='Space'&&!e.target.closest('button,input,textarea,select')){e.preventDefault();pauseProducedFilm();return;}
 if(e.key==='Tab'){
  const surface=sound.hidden?root.querySelector('.gh-cinema'):sound;
  const controls=[...surface.querySelectorAll('button,input,select,[tabindex="0"]')].filter(n=>!n.disabled&&!n.hidden&&n.getClientRects().length);
  if(!controls.length)return;
  const first=controls[0],last=controls.at(-1),active=document.activeElement;
  if(!surface.contains(active)){e.preventDefault();(e.shiftKey?last:first).focus();}
  else if(e.shiftKey&&(active===first||active===surface)){e.preventDefault();last.focus();}
  else if(!e.shiftKey&&(active===last||active===surface)){e.preventDefault();first.focus();}
 }
});

function bounds(){return {w:stage.clientWidth,h:stage.clientHeight};}
function keep(w){const b=bounds();if(b.w<=540)return;const width=Math.min(Math.max(parseFloat(w.style.width)||360,290),b.w-16),height=Math.min(Math.max(parseFloat(w.style.height)||440,270),b.h-16);w.style.width=width+'px';w.style.height=height+'px';w.style.left=Math.max(0,Math.min(parseFloat(w.style.left)||0,b.w-width))+'px';w.style.top=Math.max(0,Math.min(parseFloat(w.style.top)||0,b.h-height))+'px';}
function defaults(){const b=bounds();const cw=Math.min(550,b.w-104);Object.assign(layouts,{case:{x:96,y:23,w:cw,h:710},chat:{x:b.w-390,y:205,w:366,h:535},evidence:{x:Math.max(95,b.w-407),y:61,w:386,h:689},board:{x:99,y:42,w:Math.min(700,b.w-125),h:685},records:{x:120,y:28,w:Math.min(610,b.w-140),h:712}});Object.entries(windows).forEach(([id,w])=>{const p=layouts[id];Object.assign(w.style,{left:p.x+'px',top:p.y+'px',width:p.w+'px',height:p.h+'px'});w.dataset.max='false';keep(w);});}
function bars(){root.querySelectorAll('.gh-taskbar [data-open]').forEach(b=>{b.classList.toggle('gh-running',!windows[b.dataset.open].hidden);b.classList.toggle('gh-task-active',b.dataset.open===active&&!windows[b.dataset.open].hidden);});}
function focus(id){active=id;Object.entries(windows).forEach(([key,w])=>w.classList.toggle('gh-active',key===id&&!w.hidden));if(windows[id])windows[id].style.zIndex=++z;bars();}
function open(id){windows[id].hidden=false;focus(id);save();}
function hide(id){windows[id].hidden=true;const others=Object.entries(windows).filter(([,w])=>!w.hidden).sort((a,b)=>(+b[1].style.zIndex||0)-(+a[1].style.zIndex||0));focus(others[0]?.[0]||'');save();}
function maximize(id){const w=windows[id];if(w.dataset.max==='true'){Object.assign(w.style,JSON.parse(w.dataset.restore||'{}'));w.dataset.max='false';keep(w);}else{w.dataset.restore=JSON.stringify({left:w.style.left,top:w.style.top,width:w.style.width,height:w.style.height});Object.assign(w.style,{left:'6px',top:'6px',width:(stage.clientWidth-12)+'px',height:(stage.clientHeight-12)+'px'});w.dataset.max='true';}focus(id);save();}
function arrange(){defaults();windows.case.hidden=false;windows.chat.hidden=false;windows.evidence.hidden=true;windows.board.hidden=true;const b=bounds();if(b.w>700){const usable=b.w-30,left=usable*.55;Object.assign(windows.case.style,{left:'10px',top:'14px',width:left+'px',height:(b.h-28)+'px'});Object.assign(windows.chat.style,{left:(left+20)+'px',top:'14px',width:(usable-left)+'px',height:(b.h-28)+'px'});}focus('chat');save();}
function message(text,who){const box=document.createElement('div');box.className='gh-message'+(who==='Sie'?' gh-you':'');const label=document.createElement('div');label.className='gh-message-label';const name=document.createElement('strong');name.textContent=who;const time=document.createElement('span');time.textContent='16:20';label.append(name,time);const p=document.createElement('p');p.textContent=text;box.append(label,p);return box;}
