function snapshot(){return {version:4,audio:{...audioPrefs},onboarding:{...onboarding},investigation:JSON.parse(JSON.stringify(flow)),drafts:{...drafts},contact,sent:{...sent},pinned,active,design:{...design},windows:Object.fromEntries(Object.entries(windows).map(([id,w])=>[id,{hidden:w.hidden,left:w.style.left,top:w.style.top,width:w.style.width,height:w.style.height}]))};}
const ownSnapshots=new Set();
function save(){savedAvailable=onboarding.started||savedAvailable;if(!window.openai?.setWidgetState)return Promise.resolve(true);const privateState=snapshot();ownSnapshots.add(JSON.stringify(privateState));if(ownSnapshots.size>12)ownSnapshots.delete(ownSnapshots.values().next().value);return Promise.resolve().then(()=>window.openai.setWidgetState({modelContent:{designStudy:'Greyhaven Polizeidesktop – Tutorial · vollständiger Fall',activeWindow:active,accent:design.accent,cornerRadius:design.radius,textScale:design.textScale,investigation:{time:hhmm(flow.clock),knownDocuments:flow.known,activeTasks:pending().map(([id])=>id),tutorialComplete:flow.solved,childRescued:known('rescue'),suspectFugitive:known('fugitive')}},privateContent:privateState})).then(()=>{root.querySelector('.gh-save-error')?.remove();return true;}).catch(()=>{showSaveError();return false;});}
function restore(state){const s=state?.privateContent;if(!s||![2,3,4].includes(s.version)||ownSnapshots.has(JSON.stringify(s)))return;restoreAudio(s.audio);restoreFlow(s);restoreOnboarding(s);if(s.contact in contacts)contact=s.contact;if(s.sent){sent.ellis=!!s.sent.ellis;sent.ortiz=!!s.sent.ortiz;}pinned=!!s.pinned;root.querySelector('.gh-pinned-evidence').hidden=!pinned;if(s.design)Object.assign(design,s.design);if(s.windows)Object.entries(s.windows).forEach(([id,p])=>{if(!windows[id])return;const w=windows[id];['left','top','width','height'].forEach(k=>{if(typeof p[k]==='string'&&/^\d+(\.\d+)?px$/.test(p[k]))w.style[k]=p[k];});w.hidden=!!p.hidden;keep(w);});renderChat();renderDesign();focus(s.active in windows&&!windows[s.active].hidden?s.active:Object.keys(windows).find(id=>!windows[id].hidden)||'');}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open){open(b.dataset.open);return;}const id=b.closest('[data-window]')?.dataset.window;if(b.dataset.action){if(b.dataset.action==='max')maximize(id);else hide(id);return;}if(b.hasAttribute('data-arrange')){arrange();return;}if(b.hasAttribute('data-home')){Object.values(windows).forEach(w=>w.hidden=true);focus('');save();return;}if(b.dataset.contact){contact=b.dataset.contact;renderChat();renderDesign();save();return;}if(b.classList.contains('gh-send')){sendInvestigationMessage();return;}if(b.dataset.caseTab){root.querySelectorAll('[data-case-tab]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));root.querySelectorAll('[data-case-panel]').forEach(p=>p.hidden=p.dataset.casePanel!==b.dataset.caseTab);return;}if(b.dataset.boardTab){root.querySelectorAll('[data-board-tab]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));root.querySelectorAll('[data-board-panel]').forEach(p=>p.hidden=p.dataset.boardPanel!==b.dataset.boardTab);return;}if(b.hasAttribute('data-pin')){pinned=true;root.querySelector('.gh-pinned-evidence').hidden=false;open('board');save();}});
Object.entries(windows).forEach(([id,w])=>{w.addEventListener('pointerdown',()=>focus(id));const drag=w.querySelector('.gh-drag'),resize=w.querySelector('.gh-resize');drag.addEventListener('dblclick',()=>maximize(id));for(const [handle,isResize] of [[drag,false],[resize,true]]){handle.addEventListener('keydown',e=>{const moves={ArrowLeft:[-18,0],ArrowRight:[18,0],ArrowUp:[0,-18],ArrowDown:[0,18]};if(!moves[e.key]||stage.clientWidth<=540)return;e.preventDefault();const [dx,dy]=moves[e.key];w.dataset.max='false';w.style[isResize?'width':'left']=(parseFloat(w.style[isResize?'width':'left'])+dx)+'px';w.style[isResize?'height':'top']=(parseFloat(w.style[isResize?'height':'top'])+dy)+'px';keep(w);save();});handle.addEventListener('pointerdown',e=>{if(e.button!==0||stage.clientWidth<=540)return;e.preventDefault();focus(id);handle.setPointerCapture(e.pointerId);const x=e.clientX,y=e.clientY,l=parseFloat(w.style.left)||0,t=parseFloat(w.style.top)||0,ww=w.offsetWidth,hh=w.offsetHeight;let snapped='';function move(ev){w.dataset.max='false';if(isResize){w.style.width=(ww+ev.clientX-x)+'px';w.style.height=(hh+ev.clientY-y)+'px';}else{w.style.left=(l+ev.clientX-x)+'px';w.style.top=(t+ev.clientY-y)+'px';const r=stage.getBoundingClientRect();snapped=ev.clientX-r.left<20?'left':r.right-ev.clientX<20?'right':'';snap.hidden=!snapped;snap.style.left=snapped==='right'?'50%':'0';}keep(w);}function stop(){handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',stop);handle.removeEventListener('pointercancel',cancel);snap.hidden=true;if(snapped){const b=bounds();Object.assign(w.style,{left:snapped==='right'?b.w/2+'px':'0px',top:'0px',width:b.w/2+'px',height:b.h+'px'});}save();}function cancel(){snapped='';stop();}handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',cancel);});}});
defaults();renderChat();renderDesign();focus('case');restore(window.openai?.widgetState);initFrontDoor();
