(()=>{
const root=document.getElementById('gh-desktop-study');
const assets={"exterior":"data:image/webp;base64,","jamie":"data:image/webp;base64,","phone":"data:image/webp;base64,"};
root.style.setProperty('--gh-background-image','url("'+assets.exterior+'")');
root.querySelectorAll('[data-art]').forEach(img=>img.src=assets[img.dataset.art]);
const modal=root.querySelector('.gh-media-viewer'),canvas=modal.querySelector('.gh-media-canvas'),picture=modal.querySelector('[data-original-image]');
const titles={phone:'IMG_1042.PNG',exterior:'Harbor House · Standortansicht',jamie:'Jamie Bennett · Vermisstenfoto'};
const descriptions={phone:'E-001 · Screenshot vom Telefon der Mutter · Aufnahme des Nachrichtenverlaufs',exterior:'Harbor House · Bildkonzept für den fiktiven Schauplatz',jamie:'Jamie Bennett · fiktives Personenfoto'};
let zoom=1,ratio=1,current='phone',returnFocus=null,fitFrame=0;
// Image dimensions must not be written from a ResizeObserver of the image container.
canvas.style.minWidth='0';canvas.style.contain='size';canvas.style.scrollbarGutter='stable both-edges';
function fit(){if(fitFrame)return;fitFrame=requestAnimationFrame(()=>{fitFrame=0;if(modal.hidden||!root.isConnected||!picture.naturalWidth)return;const status=modal.querySelector('[data-zoom-status]');const label=zoom===1?'Ansicht eingepasst':Math.round(zoom*100)+' % der eingepassten Ansicht';if(status.textContent!==label)status.textContent=label;modal.querySelector('[data-zoom="in"]').disabled=zoom>=3;modal.querySelector('[data-zoom="out"]').disabled=zoom<=.75;const css=getComputedStyle(canvas);const width=canvas.clientWidth-parseFloat(css.paddingLeft)-parseFloat(css.paddingRight);const height=canvas.clientHeight-parseFloat(css.paddingTop)-parseFloat(css.paddingBottom);if(width<=0||height<=0)return;ratio=Math.min(width/picture.naturalWidth,height/picture.naturalHeight);const imageWidth=Math.floor(picture.naturalWidth*ratio*zoom)+'px';const imageHeight=Math.floor(picture.naturalHeight*ratio*zoom)+'px';if(picture.style.width!==imageWidth)picture.style.width=imageWidth;if(picture.style.height!==imageHeight)picture.style.height=imageHeight;});}
function show(key,trigger){current=key;zoom=1;returnFocus=trigger;picture.src=assets[key];picture.alt=descriptions[key];modal.querySelector('[data-media-title]').textContent=titles[key];modal.querySelector('[data-media-description]').textContent=descriptions[key];modal.hidden=false;root.querySelectorAll('.gh-window,.gh-shortcuts').forEach(el=>el.inert=true);modal.querySelector('[data-media-close]').focus();fit();canvas.scrollTop=0;canvas.scrollLeft=0;}
function close(){modal.hidden=true;root.querySelectorAll('.gh-window,.gh-shortcuts').forEach(el=>el.inert=false);returnFocus?.focus();}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.media){show(b.dataset.media,b);return;}if(b.hasAttribute('data-media-close')){close();return;}if(b.dataset.zoom){zoom=b.dataset.zoom==='fit'?1:Math.max(.75,Math.min(3,zoom+(b.dataset.zoom==='in'?.25:-.25)));fit();}});
root.addEventListener('keydown',e=>{if(modal.hidden)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const controls=[...modal.querySelectorAll('button:not(:disabled)')];const i=controls.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();controls.at(-1).focus();}else if(!e.shiftKey&&i===controls.length-1){e.preventDefault();controls[0].focus();}}});
picture.addEventListener('load',fit);window.addEventListener('resize',fit);
})();

